# Nebius blog "MLPerf Storage v3.0 results: Leading RetinaNet training on Nebius Object Storage" held against storage/storage_v30_results.json. python3 -I check_claims_storage_nebius_v30.py
import json, hashlib
FILES = ['storage/storage_v30_results.json']; RAW = {f: open(f, 'rb').read() for f in FILES}
R = json.loads(RAW[FILES[0]])['rows']; C = [r for r in R if r['division'] == 'closed']
def mk(i, q, calc, st, got, out, note): return dict(id=i, quote=q, calc=calc, stated=st, delivered=got, outcome=out, note=note, label_mismatch=False)
tr = [r for r in C if r['category'] == 'training']; ck = [r for r in C if r['category'] == 'checkpointing']
nb = lambda wl: [r for r in C if r['submitter'] == 'Nebius' and r['workload'] == wl][0]
ret = sorted([r for r in tr if r['workload'] == 'retinanet'], key=lambda r: -r['accelerators']); un = [r for r in tr if r['workload'] == 'unet3d']
N = []
top_all = sorted([r for r in C if r.get('accelerators')], key=lambda r: -r['accelerators'])
top_ck = [r for r in top_all if r['category'] == 'checkpointing'][0]
N.append(mk('NB1', 'fed 768 simulated NVIDIA B200 accelerators running the RetinaNet training workload, the highest accelerator count of any submission in this round.', 'num_accelerators in every Closed division summary.json, all categories', 'the highest accelerator count of any submission',
            f'Nebius RetinaNet {ret[0]["accelerators"]}. Next RetinaNet {ret[1]["accelerators"]} ({ret[1]["submitter"]}). Largest training entry of any workload {max(r["accelerators"] for r in tr)}. Checkpointing entries list up to {top_ck["accelerators"]} ({top_ck["submitter"]}, {top_ck["workload"]})',
            'BELOW' if top_ck['accelerators'] > ret[0]['accelerators'] else 'CONSISTENT',
            'The checkpointing rule 4.6.2 counts simulated accelerators as the number of processes, so the 1,024 in the Azure and Everpure llama3-1t summaries is a count of simulated accelerators in the file. The post limits itself to RetinaNet two sentences later (next row).'))
N.append(mk('NB2', 'Nebius ran RetinaNet at the highest accelerator count of all submissions, regardless of storage architecture.', 'RetinaNet Closed entries, accelerators', 'highest RetinaNet accelerator count of all submissions', f'Nebius {ret[0]["accelerators"]} against {ret[1]["accelerators"]} ({ret[1]["submitter"]}, file storage) and {ret[3]["accelerators"]} ({ret[3]["submitter"]})', 'CONSISTENT' if ret[0]['submitter'] == 'Nebius' else 'BELOW', 'Accelerator counts are read from num_accelerators in the summary files.'))
obj = sorted([r for r in tr if r['workload'] == 'retinanet' and r.get('benchmark_API') == 'object'], key=lambda r: -r['accelerators'])
N.append(mk('NB3', 'that throughput is more than twice the next-best result.', 'RetinaNet object storage entries, samples per second (mean of the last five runs)', 'more than twice the next-best object storage result',
            f'Nebius {obj[0]["samples_per_s"]:.0f} samples/s, next {obj[1]["samples_per_s"]:.0f} ({obj[1]["submitter"]}), ratio {obj[0]["samples_per_s"]/obj[1]["samples_per_s"]:.3f}. Accelerators {obj[0]["accelerators"]} against {obj[1]["accelerators"]}, ratio {obj[0]["accelerators"]/obj[1]["accelerators"]:.3f}',
            'CONSISTENT' if obj[0]['samples_per_s'] > 2 * obj[1]['samples_per_s'] else 'BELOW', 'The post says "that throughput", read as samples per second. Bandwidth in GiB/s gives ' + f'{obj[0]["io_GiB_per_s"]/obj[1]["io_GiB_per_s"]:.3f}.'))
uo = sorted([r for r in un if r.get('benchmark_API') == 'object'], key=lambda r: -r['accelerators'])
N.append(mk('NB4', 'Nebius posted the highest Unet3D accelerator count among object storage submissions this round.', 'Unet3D Closed entries with an object benchmark API', 'highest Unet3D accelerator count among object storage submissions', f'Nebius {uo[0]["accelerators"]}, next {uo[1]["accelerators"]} ({uo[1]["submitter"]})', 'CONSISTENT' if uo[0]['submitter'] == 'Nebius' else 'BELOW', 'Object storage is read from benchmark_API in each system description.'))
osub = sorted({r['submitter'] for r in C if r.get('benchmark_API') == 'object'}); s3sub = sorted({r['submitter'] for r in C if r.get('uri_scheme') == 's3'})
N.append(mk('NB5', 'only three benchmarked an S3 object storage backend.', 'Closed submitters with an object benchmark API in a system description, and the storage URI scheme where the file names one', 'three of 19 Closed submitters used an S3 object storage backend', f'{len({r["submitter"] for r in C})} Closed submitters. Object benchmark API: {", ".join(osub)}. The file names an s3 scheme for: {", ".join(s3sub)}', 'CANNOT_TELL' if len(osub) == 3 and len(s3sub) < 3 else ('CONSISTENT' if len(osub) == 3 else 'BELOW'),
            'The count of three matches. Whether the other two use an S3 interface is not stated in their system files.'))
n1, n2 = nb('retinanet'), nb('unet3d')
N.append(mk('NB6', 'sustained an aggregate 341,881 samples per second while maintaining 88.4% accelerator utilization.', 'RetinaNet entry, mean of runs 2 to 6 (run 1 is the warm-up, Rules 2.1.17)', '341,881 samples/s at 88.4% utilization', f'{n1["samples_per_s"]:.0f} samples/s at {n1["au_pct"]:.1f}%, {n1["io_GiB_per_s"]:.2f} GiB/s', 'CONSISTENT' if round(n1['samples_per_s']) == 341881 and round(n1['au_pct'], 1) == 88.4 else 'BELOW', 'The mean of all six runs is lower; the post uses the five after the warm-up, as the rules say.'))
N.append(mk('NB7', '21 simulated B200 accelerators across 21 client nodes, and Object Storage sustained 114.45 GiB/s of aggregate read throughput at 92.5% accelerator utilization.', 'Unet3D entry, mean of runs 2 to 6', '21 accelerators, 21 nodes, 114.45 GiB/s, 92.5%', f'{n2["accelerators"]} accelerators, {n2["hosts"]} hosts, {n2["io_GiB_per_s"]:.2f} GiB/s, {n2["au_pct"]:.1f}%', 'CONSISTENT' if (n2['accelerators'], n2['hosts'], round(n2['io_GiB_per_s'], 2), round(n2['au_pct'], 1)) == (21, 21, 114.45, 92.5) else 'BELOW', 'Bandwidth is the file value in MiB/s divided by 1,024.'))
c8, c70 = nb('llama3-8b'), nb('llama3-70b')
N.append(mk('NB8', 'Checkpoint write bandwidth scaled from 2.81 GiB/s on one client node to 19.46 GiB/s on eight.', 'Nebius llama3-8b and llama3-70b checkpointing summaries', '2.81 to 19.46 GiB/s write, one to eight client nodes', f'{c8["write_GiB_per_s"]:.2f} GiB/s on {c8["hosts"]} host, {c70["write_GiB_per_s"]:.2f} GiB/s on {c70["hosts"]} hosts', 'CONSISTENT' if (round(c8['write_GiB_per_s'], 2), round(c70['write_GiB_per_s'], 2), c8['hosts'], c70['hosts']) == (2.81, 19.46, 1, 8) else 'BELOW', 'The file field is named GB per second; the post and the rules call the unit GiB/s.'))
N.append(mk('NB9', 'aggregate read bandwidth increased from 7.14 GiB/s to 38.27 GiB/s.', 'same two summaries, load_checkpoint_io_mean', '7.14 to 38.27 GiB/s read', f'{c8["read_GiB_per_s"]:.2f} and {c70["read_GiB_per_s"]:.2f} GiB/s', 'CONSISTENT' if (round(c8['read_GiB_per_s'], 2), round(c70['read_GiB_per_s'], 2)) == (7.14, 38.27) else 'BELOW', ''))
nbr = [r for r in C if r['submitter'] == 'Nebius']
N.append(mk('NB10', 'All four Closed division results ran on Object Storage with the Enhanced storage class in one of our production regions.', 'Nebius Closed entries and their system descriptions', 'four Closed results, all on Object Storage with the Enhanced storage class', f'{len(nbr)} Closed entries ({", ".join(sorted(r["workload"] for r in nbr))}), benchmark API {sorted({r.get("benchmark_API") for r in nbr})}, URI scheme {sorted({r.get("uri_scheme") for r in nbr})}', 'CANNOT_TELL', 'The count and the object API match. A storage class and a production region are not fields in the system files.'))
N.append(mk('NB11', 'Client nodes ran as publicly available CPU-only virtual machines (the AMD EPYC Genoa cpu-d3 preset) on Ubuntu 24.04 over Ethernet, with capped memory.', 'system description yaml for the RetinaNet entry', 'cpu-d3, AMD EPYC Genoa, Ubuntu 24.04, Ethernet', 'chassis model_name cpu-d3, cpu_model AMD EPYC-Genoa Processor, operating_system Ubuntu 24.04, networking type ethernet (400 Gb/s)', 'CONSISTENT', 'Read by hand from storage/v3.0/closed/Nebius/systems/nebius-s3-retinanet-32nx24-cm64.yaml. Memory is listed as 61 GiB per client.'))
N.append(mk('NB12', 'entry v3.0-0074.', 'public entry IDs are on the MLCommons results page, not in the results repository', 'RetinaNet is entry v3.0-0074', 'the repository holds no entry IDs', 'CANNOT_TELL', 'The repository is organized by submitter and system name.'))
json.dump(dict(source=FILES + ['raw/storage_nebius_v30.txt'], sha256=[hashlib.sha256(RAW[f]).hexdigest() for f in FILES], claims=N), open('claims_storage_nebius_v30.json', 'w'), indent=1)
for c in N: print(c['id'], c['outcome'], '|', c['delivered'][:230])
